import{_ as t,h as r,i as A,c as i,v as e,p as o,x as l,m as n,e as s,S as D}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"原子层沉积 ALD 与原子层刻蚀","description":"","frontmatter":{"title":"原子层沉积 ALD 与原子层刻蚀","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ald-ale.md","filePath":"llm/ald-ale.md","lastUpdated":1788454257000}'),d={name:"llm/ald-ale.md"};function p(h,a,L,B,c,m){const E=r("Mermaid");return A(),i("div",null,[a[1]||(a[1]=e('<h1 id="原子层沉积-ald-与原子层刻蚀" tabindex="-1">原子层沉积 ALD 与原子层刻蚀 <a class="header-anchor" href="#原子层沉积-ald-与原子层刻蚀" aria-label="Permalink to &quot;原子层沉积 ALD 与原子层刻蚀&quot;">​</a></h1><div class="epigraph"><p>当空腔的宽高比让连续流沉积和溅射刻蚀都失去选择比时，只能把生长与去除收成自限制的半反应循环：每圈一层，或每圈一个原子级薄层。</p><footer>—— 对照薄膜与刻蚀的自限制化学，以及 GAA 空腔填充的公开工艺约束</footer></div><p>高介电栅氧、功函数金属、侧墙、阻挡层，在平面时代可以用 CVD 或 PVD 对付。 <a href="/llm/finfet-gaa">GAA 纳米片</a> 把这些膜塞进片间距只有数纳米的环绕空腔：先到的表面必须均匀长满，不能在入口封口留下空洞；去掉牺牲 SiGe 时又不能啃掉作为沟道的硅。原子层沉积（ALD）用交替的自限制半反应，生长量由表面位点而不是通量梯度决定。原子层刻蚀（ALE）把「改性 + 去除」收成循环，争取每个循环固定减薄，并给出相对连续等离子体更宽的选择比窗口。两者是同一哲学的正反面，在先进节点里成对出现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非自限制沉积在深孔里呈现入口厚、底部薄：前驱体在口部耗尽。PVD 更有方向性，侧壁覆盖差。纳米片的栅金属必须从四面等厚包住每一片，厚度差几个埃就会让阈值分裂。连续等离子体刻蚀靠离子能量与化学，能量一大就损伤沟道，能量一小就停在难以挥发的产物上，工艺窗口窄。</p><p>需要的是：厚度以循环计而不是以秒计；覆盖由化学吸附饱和保证；刻蚀深度与损伤解耦。问题是吞吐——循环天然慢——以及材料表：不是每一种金属或介质都有干净的 ALD/ALE 化学。产线要在「够保形」和「每小时晶圆」之间找能交货的循环。</p><h3 id="自限制不是无限保形" tabindex="-1">自限制不是无限保形 <a class="header-anchor" href="#自限制不是无限保形" aria-label="Permalink to &quot;自限制不是无限保形&quot;">​</a></h3><p>ALD 的饱和依赖于前驱体扩散进空腔、副产物扩散出来、以及表面位点真正饱和。高深宽比下，若半反应时间不够，底部仍欠饱和，保形性神话破产。ALE 的改性步若打进沟道，或去除步有物理溅射分量，循环就不再自限制。把 ALD/ALE 写成「原子精度开关」会忽略时间与损伤这两条轴。</p><p><span class="marginnote">生长/循环（GPC）是平均值。成核延迟、衬底依赖和岛状生长会让前几十圈的厚度不可外推。GAA 片上的功函数金属往往就在这个成核区里工作，校准必须用真实空腔计量，而不是平面监控片。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ALD 经典图像是两个半反应：例如含金属前驱体饱和吸附，惰性吹扫，再与氧源或氮源反应，再吹扫。每循环生长通常是一埃量级的分数到一层。温度窗口要落在：够反应、又不够热解成 CVD。先进逻辑用它做高 K、TiN/TiAlC 一类功函数叠层、侧墙、衬垫；三维结构里还做选择性 ALD（只在介质或只在金属上长）以减少对准。</p><p>ALE 分等离子体辅助与热 ALE。前者常用卤化或氟化改性表面，再用低能离子或配体交换把改性层剥掉；后者完全靠热化学，损伤更低、速率更慢。与 ALD 对偶的材料对（如某些氧化物的氟化再配体去除）最干净。GAA 释放与内间隔，常是选择性蚀刻 + ALE 修整的组合：大块去掉用高选择化学，界面用循环修到目标内间隔厚度。</p><h3 id="选择比窗口与协同" tabindex="-1">选择比窗口与协同 <a class="header-anchor" href="#选择比窗口与协同" aria-label="Permalink to &quot;选择比窗口与协同&quot;">​</a></h3><p>ALE 文献里的「协同」指：只有改性加上去除都发生时才有可观速率，缺一步则几乎停。这给出对掩模或沟道的选择比。窗口随离子能量、剂量和温度移动。量产要把窗口做宽到能覆盖晶圆内与批次间漂移，否则原子级循环会变成原子级不稳定。ALD 同样有窗口：前驱体热解或刻蚀性氧源会把 ALD 拖成 CVD 或把已长的膜啃掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自限制把厚度从「通量 × 时间」改成「位点密度 × 循环数」。深宽比进入的是循环时间（要饱和），而不是最终厚度剖面——只要真饱和。这解释了为什么 ALD 能填纳米腔：入口饱和后不再继续长（该半反应内），前驱体能继续往里走。若某一半反应有 CVD 分量，入口会封口，后面全是空洞，GAA 栅电阻和阈值一起坏。</p><p>ALE 把损伤限制在改性层厚度。离子用来协助脱附而不是用来砸体材料，沟道迁移率才保得住。代价是速率：每循环埃级，去掉十纳米要很多循环。与 <a href="/llm/euv-resist">光刻胶</a> 的薄胶高选择转移类似：纵向预算变薄之后，转移与修整必须改成循环工艺，否则一次过刻就把纳米片削断。</p><p><span class="marginnote">ALD 与 ALE 不是「更高级的 CVD/RIE」。有 CVD 分量的所谓 ALD、有溅射分量的所谓 ALE，只是借用了循环的名字。判断标准是饱和曲线：剂量加大一截，厚度或去除是否停住。</span></p><h3 id="与设备产能的耦合" tabindex="-1">与设备产能的耦合 <a class="header-anchor" href="#与设备产能的耦合" aria-label="Permalink to &quot;与设备产能的耦合&quot;">​</a></h3><p>循环慢，就要多腔、多片、集群。前驱体贵且有毒性或腐蚀性，尾气与腔体涂层成为运行成本。GAA 量产等于同时买通 ALD/ALE 化学、计量（光学与电学）和腔体颗粒控制。设备产能会像 EUV 一样成为节点节奏的隐藏约束：晶体管架构图纸画得出，薄膜循环排不出。</p>',20)),(A(),o(D,null,{default:l(()=>[s(E,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%8D%8A%E5%8F%8D%E5%BA%94%20A%3A%20%E5%90%B8%E9%99%84%E9%A5%B1%E5%92%8C%22%5D%20--%3E%20P1%5B%22%E5%90%B9%E6%89%AB%22%5D%0A%20%20P1%20--%3E%20S2%5B%22%E5%8D%8A%E5%8F%8D%E5%BA%94%20B%3A%20%E5%8F%8D%E5%BA%94%E9%A5%B1%E5%92%8C%22%5D%0A%20%20S2%20--%3E%20P2%5B%22%E5%90%B9%E6%89%AB%22%5D%0A%20%20P2%20--%3E%20S1%0A%20%20S1%20--%3E%20ALD%5B%22ALD%3A%20%E5%8E%9A%E5%BA%A6%E6%8C%89%E5%BE%AA%E7%8E%AF%E5%8A%A0%22%5D%0A%20%20M%5B%22%E6%94%B9%E6%80%A7%E8%A1%A8%E9%9D%A2%22%5D%20--%3E%20R%5B%22%E5%8E%BB%E9%99%A4%E6%94%B9%E6%80%A7%E5%B1%82%22%5D%0A%20%20R%20--%3E%20M%0A%20%20M%20--%3E%20ALE%5B%22ALE%3A%20%E5%8E%9A%E5%BA%A6%E6%8C%89%E5%BE%AA%E7%8E%AF%E5%87%8F%22%5D%0A%20%20ALD%20--%3E%20GAA%5B%22%E7%BA%B3%E7%B1%B3%E8%85%94%E4%BF%9D%E5%BD%A2%E5%A1%AB%E5%85%85%22%5D%0A%20%20ALE%20--%3E%20REL%5B%22%E9%87%8A%E6%94%BE%20%2F%20%E5%86%85%E9%97%B4%E9%9A%94%E4%BF%AE%E6%95%B4%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不是所有层都值得 ALD/ALE。厚的层间介质、大开口的金属，CVD/PVD 的吞吐更好。滥用循环工艺会把成本与颗粒风险抬到收益以上。选择性 ALD 的缺陷模式是漏选与过选，电学上表现为短路或开路，检测比厚度更难。前驱体供应链与出口管制会限制化学选择，工艺集成不能假设「文献里那个配体一定能买到」。</p><p>与光刻的关系：节距仍由 EUV 与 <a href="/llm/opc">OPC</a> 定，ALD/ALE 决定在这个节距里薄膜能不能均匀存在。两者一起失败时，问题会表现为「GAA 良率」，根因可能在空腔填充，也可能在孔的随机缺失。</p><p><span class="marginnote">报告 ALD 厚度时写清：平面还是结构内、是否过了成核区、用什么计量。把平面 XRR 的数字当成纳米片上的功函数厚度，是常见的乐观偏差。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ALD 用自限制半反应在高深宽比里做保形生长，厚度以循环计。</li><li>ALE 用改性—去除循环做低损伤减薄，并争取协同带来的选择比。</li><li>GAA 的释放、内间隔和环绕栅填充把二者从可选项变成必要步骤。</li><li>真自限制看饱和曲线；带 CVD/溅射分量的循环只是名义原子层。</li><li>吞吐、前驱体与颗粒控制决定能否量产，不只看截面 TEM 好看。</li><li>薄膜循环不替代光刻节距，但会决定该节距下器件变差。</li><li>出处：ALD/ALE 自限制化学；先进逻辑 GAA 集成公开论述。</li></ul>',6))])}const f=t(d,[["render",p]]);export{u as __pageData,f as default};
